 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The most common nonzero color is the field; the other nonzero color(s)
    # form the template to stamp into matching all-zero placements.
    counts = Counter(v for row in grid for v in row if v != 0)
    field = counts.most_common(1)[0][0]
    marker = next((v for v in counts if v != field), None)
    if marker is None:
        return [row[:] for row in grid]
    shape = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    minr, maxr = min(r for r, c in shape), max(r for r, c in shape)
    minc, maxc = min(c for r, c in shape), max(c for r, c in shape)
    shape = [(r-minr, c-minc) for r, c in shape]
    for r in range(h-(maxr-minr)):
        for c in range(w-(maxc-minc)):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(grid[rr][cc] == 0 for rr, cc in cells):
                for rr, cc in cells:
                    out[rr][cc] = marker
    return out
